"use strict";(self.webpackChunkgbc_documentation=self.webpackChunkgbc_documentation||[]).push([[164],{9842:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"gbc-open-source-release","metadata":{"permalink":"/gbc/blog/gbc-open-source-release","editUrl":"https://github.com/sjtu-mvasl-robotics/sjtu-mvasl-robotics.github.io/tree/main/gbc/blog/2025-08-14-gbc-open-source-release.md","source":"@site/blog/2025-08-14-gbc-open-source-release.md","title":"GBC Project Now Open Source!","description":"We are thrilled to announce that the GBC (Generalized Behavior Cloning) framework is now officially open source! \ud83c\udf89 Researchers and developers worldwide can now access and use our codebase for their humanoid researches!","date":"2025-08-14T00:00:00.000Z","tags":[{"inline":false,"label":"News","permalink":"/gbc/blog/tags/news","description":"Latest news and announcements"},{"inline":false,"label":"Announcements","permalink":"/gbc/blog/tags/announcements","description":"Important announcements and updates"},{"inline":false,"label":"Open Source","permalink":"/gbc/blog/tags/open-source","description":"Open source project announcements"}],"readingTime":3.78,"hasTruncateMarker":true,"authors":[{"name":"Yifei Yao","title":"GBC Project Lead, SJTU MVASL Lab","url":"https://securitycfs.github.io","page":{"permalink":"/gbc/blog/authors/yifei"},"socials":{"github":"https://github.com/securityCFS"},"imageURL":"https://github.com/securityCFS.png","key":"yifei"}],"frontMatter":{"slug":"gbc-open-source-release","title":"GBC Project Now Open Source!","authors":["yifei"],"tags":["news","announcement","open-source"],"date":"2025-08-14T00:00:00.000Z"},"unlisted":false,"nextItem":{"title":"GBC Project Will Soon be Available!","permalink":"/gbc/blog/gbc-pre-open-source"}},"content":"We are thrilled to announce that the **GBC (Generalized Behavior Cloning)** framework is now officially open source! \ud83c\udf89 Researchers and developers worldwide can now access and use our codebase for their humanoid researches!\\n\\n\x3c!--truncate--\x3e\\n\\n## \ud83d\udce6 Open Source Repositories\\n\\nWe have released our key codebases on GitHub:\\n\\n- **GBC Core Framework**: [https://github.com/sjtu-mvasl-robotics/GBC](https://github.com/sjtu-mvasl-robotics/GBC)\\n  - Contains complete motion retargeting pipeline\\n  - Provides comprehensive training environment and tools\\n  - Supports multiple humanoid robot platforms\\n  \\n- **Reinforcement Learning Algorithm Library**: [https://github.com/sjtu-mvasl-robotics/rsl_rl](https://github.com/sjtu-mvasl-robotics/rsl_rl)\\n  - Implements MMPPO, PPO, and other core algorithms\\n  - Provides efficient distributed training architecture\\n  - Includes MMTransformer network implementation\\n\\n## \ud83c\udf1f GBC Framework Highlights\\n\\nThe GBC framework is a comprehensive, unified solution designed to solve the end-to-end challenge from human motion to robot action:\\n\\n### 1. Adaptive Data Processing Pipeline\\n- Leverages a differentiable IK network to automatically retarget any human MoCap data to any humanoid robot\\n- Provides real-time, efficient, and physically feasible kinematic retargeting\\n- Comprehensive data post-processing capabilities\\n\\n### 2. Innovative Network Architecture & Enhanced PPO Algorithm\\n- Employs MMTransformer to seamlessly integrate robot environment observations with reference actions\\n- Enables single-action to multi-action imitation through our MMPPO framework\\n- Supports switching freely between action tracking and reinforcement learning instruction following modes\\n\\n### 3. Cross-Platform Testing and Validation\\n- Train policies in Isaac Sim\\n- Validate policy transfer in MuJoCo (evaluation code coming soon)\\n- Provides comprehensive evaluation framework\\n\\n## \ud83d\udccb Release Roadmap\\n\\n| Component | Status | Description |\\n|------|------|------|\\n| Retargeting Pipeline | \u2705 Released | Complete framework for retargeting human motion capture data to any humanoid robot morphology |\\n| RL+IL Repository | \u2705 Released | Core reinforcement learning and imitation learning algorithms used in GBC |\\n| Reinforcement Learning Library | \u2705 Released | Associated RL algorithm library with implementations of PPO, MMPPO, and custom extensions |\\n| Documentation & Tutorials | \u2705 Released | Basic usage documentation and getting-started tutorials |\\n| Robot-Specific Training Demos | \u2705 Released | Demonstration examples for specific robot configurations |\\n| Training Scripts for All Test Robots | \u23f3 Coming Soon | Complete training scripts for all robots evaluated in the paper |\\n| Demo Videos | \ud83d\udd1c Imminent | Comprehensive demonstration videos of the framework in action |\\n| Hugging Face Checkpoints | \ud83d\udd1c Imminent | Pre-trained model checkpoints available on Hugging Face |\\n| Tutorial Videos | \u23f3 Planned | Step-by-step video tutorials for using the GBC framework |\\n| Advanced Features Documentation | \u23f3 Planned | Detailed tutorials for advanced features (AMP, DAgger, Symmetry Augmentation, etc.) |\\n| MuJoCo Sim2Sim Validation | \u23f3 Planned | Scripts for validating sim-to-sim transfer using MuJoCo |\\n| Deployment Code | \u23f3 Planned | Deployment code for currently available robot configurations |\\n\\n## \ud83d\udee0\ufe0f Getting Started\\n\\n### Prerequisites\\n\\nBefore starting, ensure you have all the necessary prerequisites installed on your system, including Python, CUDA, Isaac Lab/Sim (optional), and appropriate hardware.\\n\\n### Installation Steps\\n\\n1. **Set up your environment**\\n   ```bash\\n   # Create and activate conda environment\\n   conda create -n GBC python=3.10\\n   conda activate GBC\\n   ```\\n\\n2. **Install GBC and dependencies**\\n   ```bash\\n   # Create and navigate to GBC directory\\n   mkdir GBC && cd GBC\\n\\n   # Clone GBC repository with all submodules\\n   git clone https://github.com/sjtu-mvasl-robotics/GBC.git --recursive\\n   cd GBC\\n   \\n   # If you have Isaac Lab installed, remove its auto-installed rsl_rl first\\n   pip uninstall rsl_rl\\n   \\n   # Install GBC and its dependencies\\n   pip install -e .\\n   cd dependencies/rsl_rl\\n   pip install -e .\\n   ```\\n\\n3. **Verify installation**\\n   ```bash\\n   python verify_installation.py\\n   ```\\n   \\n   Successful installation should show:\\n   ```\\n   \u2705 GBC Core: OK\\n   \u2705 SMPL Support: OK\\n   \u2705 Isaac Lab: OK (if installed)\\n   \u2705 rsl_rl: OK (if installed, and has dev tag)\\n   ```\\n\\n## \ud83c\udfa5 Coming Soon\\n\\nWe are actively preparing the following content to be released soon:\\n\\n- **Demo Videos** - Showcasing the GBC framework in action on various humanoid robots\\n- **Tutorial Videos** - Step-by-step video guides on how to use the GBC framework\\n- **Pre-trained Models** - Pre-trained checkpoints available on Hugging Face\\n\\n## \ud83e\udd1d Collaboration Opportunity\\n\\nWe are actively seeking to test and validate our algorithms on additional humanoid robot platforms. If you are a researcher or industry partner working with humanoid robots and are interested in collaboration, we\'d love to discuss potential partnerships. Our framework is designed to be adaptable to various morphologies, and we\'re excited to expand our testing across diverse platforms.\\n\\n## \ud83d\ude4f Community Support\\n\\nWe warmly welcome community feedback, suggestions, and improvements to the algorithm and its implementation! Your pull requests and contributions are greatly appreciated and vital to the continued development of this project.\\n\\n## \ud83d\udcde Contact Us\\n\\nIf you have any questions or feedback, please feel free to reach out to us:\\n\\n- First author\'s email: [Yifei Yao](mailto:godchaser@sjtu.edu.cn)\\n- Corresponding author\'s email: [Jun-Guo Lu](mailto:jglu@sjtu.edu.cn)\\n\\nIf you want to contact our laboratory for more information, it is recommended to reach out to the corresponding author. For technical inquiries, please contact the first author.\\n\\n---\\n\\n*We look forward to seeing the amazing humanoid robot applications the community creates with the GBC framework!*"},{"id":"gbc-pre-open-source","metadata":{"permalink":"/gbc/blog/gbc-pre-open-source","editUrl":"https://github.com/sjtu-mvasl-robotics/sjtu-mvasl-robotics.github.io/tree/main/gbc/blog/2025-07-31-gbc-pre-open-source.md","source":"@site/blog/2025-07-31-gbc-pre-open-source.md","title":"GBC Project Will Soon be Available!","description":"We\'re excited to announce that the GBC (Generalized Behavior Cloning Framework) is in its final stages of preparation for public release! \ud83c\udf89","date":"2025-07-31T00:00:00.000Z","tags":[{"inline":false,"label":"News","permalink":"/gbc/blog/tags/news","description":"Latest news and announcements"},{"inline":false,"label":"Announcements","permalink":"/gbc/blog/tags/announcements","description":"Important announcements and updates"},{"inline":false,"label":"Open Source","permalink":"/gbc/blog/tags/open-source","description":"Open source project announcements"}],"readingTime":1.11,"hasTruncateMarker":true,"authors":[{"name":"Yifei Yao","title":"GBC Project Lead, SJTU MVASL Lab","url":"https://securitycfs.github.io","page":{"permalink":"/gbc/blog/authors/yifei"},"socials":{"github":"https://github.com/securityCFS"},"imageURL":"https://github.com/securityCFS.png","key":"yifei"}],"frontMatter":{"slug":"gbc-pre-open-source","title":"GBC Project Will Soon be Available!","authors":["yifei"],"tags":["news","announcement","open-source"],"date":"2025-07-31T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"GBC Project Now Open Source!","permalink":"/gbc/blog/gbc-open-source-release"},"nextItem":{"title":"GBC Project Documents are Ready to Launch!","permalink":"/gbc/blog/gbc-documentation-ready"}},"content":"We\'re excited to announce that the **GBC (Generalized Behavior Cloning Framework)** is in its final stages of preparation for public release! \ud83c\udf89\\n\\n\x3c!--truncate--\x3e\\n\\n## \ud83d\udccb Current Status\\n\\nOur team is currently conducting comprehensive **code review, refinement, and debugging** to ensure the highest quality open-source release. We want to make sure that when GBC becomes available, it\'s ready for researchers and developers worldwide to use effectively.\\n\\n## \ud83d\uddd3\ufe0f Release Timeline\\n\\n**Target Release Date**: **Before August 10, 2025** \ud83d\udcc5\\n\\nThe complete GBC framework will be available at:\\n**https://github.com/sjtu-mvasl-robotics/GBC**\\n\\n## \ud83d\udcc4 Paper & Code Release\\n\\nThe open-source code release is planned to coincide with our research paper publication on arXiv. Both the technical documentation and the complete implementation will be available simultaneously, providing you with:\\n\\n- \ud83d\udcda **Comprehensive documentation** (like this site!)\\n- \ud83d\udee0\ufe0f **Complete source code** with examples\\n- \ud83e\udd16 **Robot configuration templates** for multiple platforms\\n- \ud83d\udcd6 **Academic paper** with detailed methodology\\n\\n## \ud83d\ude4f Thank You for Your Interest!\\n\\nWe\'re incredibly grateful for the enthusiasm and interest the robotics community has shown in GBC. Your support motivates us to deliver the best possible framework for humanoid robot learning and motion imitation.\\n\\n## \ud83d\udd14 Stay Updated\\n\\n- \u2b50 **Star** our repository: https://github.com/sjtu-mvasl-robotics/GBC\\n- \ud83d\udcd6 **Follow** our documentation progress on this site\\n- \ud83d\udde8\ufe0f **Join** our GitHub Discussions for early access to development updates\\n\\n**The future of humanoid robotics is almost here!** \ud83e\udd16\u2728\\n\\n---\\n\\n*Stay tuned for the official release announcement!*"},{"id":"gbc-documentation-ready","metadata":{"permalink":"/gbc/blog/gbc-documentation-ready","editUrl":"https://github.com/sjtu-mvasl-robotics/sjtu-mvasl-robotics.github.io/tree/main/gbc/blog/2025-07-30-gbc-documentation-ready.md","source":"@site/blog/2025-07-30-gbc-documentation-ready.md","title":"GBC Project Documents are Ready to Launch!","description":"We\'re thrilled to announce that the GBC (Generalized Behavior Cloning Framework) documentation is now complete and ready for the community! \ud83c\udf89","date":"2025-07-30T00:00:00.000Z","tags":[{"inline":false,"label":"News","permalink":"/gbc/blog/tags/news","description":"Latest news and announcements"},{"inline":false,"label":"Announcements","permalink":"/gbc/blog/tags/announcements","description":"Important announcements and updates"},{"inline":false,"label":"Documentation","permalink":"/gbc/blog/tags/documentation","description":"Documentation updates and improvements"}],"readingTime":1.64,"hasTruncateMarker":true,"authors":[{"name":"Yifei Yao","title":"GBC Project Lead, SJTU MVASL Lab","url":"https://securitycfs.github.io","page":{"permalink":"/gbc/blog/authors/yifei"},"socials":{"github":"https://github.com/securityCFS"},"imageURL":"https://github.com/securityCFS.png","key":"yifei"}],"frontMatter":{"slug":"gbc-documentation-ready","title":"GBC Project Documents are Ready to Launch!","authors":["yifei"],"tags":["news","announcement","documentation"],"date":"2025-07-30T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"GBC Project Will Soon be Available!","permalink":"/gbc/blog/gbc-pre-open-source"},"nextItem":{"title":"GBC Project Blog Test","permalink":"/gbc/blog/gbc-test"}},"content":"We\'re thrilled to announce that the **GBC (Generalized Behavior Cloning Framework) documentation** is now complete and ready for the community! \ud83c\udf89\\n\\n\x3c!--truncate--\x3e\\n\\n## \ud83d\udcd6 What\'s Available Now\\n\\nThe majority of GBC documentation preparation work has been completed! Our comprehensive documentation suite currently includes:\\n\\n### \ud83d\udee0\ufe0f **Complete User Journey**\\n- **\ud83d\udce6 Installation Guide** - Step-by-step setup instructions\\n- **\u2699\ufe0f Configuration Tutorial** - Environment and robot configuration\\n- **\ud83c\udfaf Training Guide** - From basic RL to advanced imitation learning\\n- **\ud83d\udd27 Debugging Manual** - Troubleshooting and optimization tips\\n- **\ud83d\ude80 Deployment Guide** - Real robot deployment strategies\\n\\n### \ud83d\udccb **Comprehensive API Documentation**\\n- **\ud83d\udd0d Complete API Reference** - All interfaces and functions documented\\n- **\ud83d\udca1 Code Examples** - Practical usage demonstrations\\n- **\ud83e\udd16 Robot Integration** - Platform-specific configurations\\n- **\ud83d\udcca Training Utilities** - Data processing and evaluation tools\\n\\n## \ud83d\udea7 What\'s Coming Next\\n\\nWhile our core documentation is complete, we\'re planning to add advanced tutorials for power users:\\n\\n### \ud83d\udd2e **Advanced Features (Coming Soon)**\\n- **\ud83d\udc41\ufe0f Custom Observation Design** - Define your own observation spaces\\n- **\ud83d\udd04 Custom Symmetry Networks** - Create robot-specific symmetry mappings\\n- **\ud83c\udfad AMP Integration** - Advanced training with Adversarial Motion Prior\\n- **\u26a1 Model Distillation** - Create lightweight models for deployment\\n- **\ud83e\udde0 Advanced Training Techniques** - Expert-level optimization strategies\\n\\n*These advanced tutorials will be added as time permits, so stay tuned!* \u23f0\\n\\n## \ud83c\udf1f **Documentation Highlights**\\n\\nOur documentation is designed to be:\\n- **\ud83d\udcda Beginner-Friendly** - Start from zero and become an expert\\n- **\ud83c\udfaf Task-Oriented** - Organized by what you want to accomplish\\n- **\ud83d\udcbb Code-Rich** - Plenty of examples you can copy and run\\n- **\ud83e\udd16 Robot-Agnostic** - Works with various humanoid platforms\\n- **\ud83d\udd04 Continuously Updated** - Growing with community feedback\\n\\n\\n## \ud83d\ude4f **Community Driven**\\n\\nThis documentation is built for the robotics community, by the community. We encourage:\\n\\n- **\ud83d\udc1b Bug Reports** - Help us improve the docs\\n- **\ud83d\udca1 Feature Requests** - Suggest new tutorials\\n- **\ud83d\udcdd Contributions** - Share your own examples and tips\\n- **\ud83d\udde8\ufe0f Discussions** - Join our community conversations\\n\\n## \ud83d\udd17 **Explore Now**\\n\\nThe documentation is live and ready for exploration! Whether you\'re a researcher looking to reproduce results, a developer building new applications, or a student learning about humanoid robotics, you\'ll find everything you need to get started with GBC.\\n\\n**Happy Learning!** \ud83e\udd16\ud83d\udcda\\n\\n---\\n\\n*The GBC team is committed to making humanoid robot development accessible to everyone. Let\'s build the future of robotics together!*"},{"id":"gbc-test","metadata":{"permalink":"/gbc/blog/gbc-test","editUrl":"https://github.com/sjtu-mvasl-robotics/sjtu-mvasl-robotics.github.io/tree/main/gbc/blog/2025-05-26-test.md","source":"@site/blog/2025-05-26-test.md","title":"GBC Project Blog Test","description":"This is just a test.","date":"2025-05-26T00:00:00.000Z","tags":[{"inline":false,"label":"News","permalink":"/gbc/blog/tags/news","description":"Latest news and announcements"},{"inline":false,"label":"Announcements","permalink":"/gbc/blog/tags/announcements","description":"Important announcements and updates"}],"readingTime":0.03,"hasTruncateMarker":false,"authors":[{"name":"Yifei Yao","title":"GBC Project Lead, SJTU MVASL Lab","url":"https://securitycfs.github.io","page":{"permalink":"/gbc/blog/authors/yifei"},"socials":{"github":"https://github.com/securityCFS"},"imageURL":"https://github.com/securityCFS.png","key":"yifei"}],"frontMatter":{"slug":"gbc-test","title":"GBC Project Blog Test","authors":["yifei"],"tags":["news","announcement"],"date":"2025-05-26T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"GBC Project Documents are Ready to Launch!","permalink":"/gbc/blog/gbc-documentation-ready"}},"content":"This is just a test."}]}}')}}]);